const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time
    const pt = ee.Geometry.Point([104.238631, 40.923221]);
    const region = pt.buffer(50000);
    const scale = 10000; // 10 km

    const datasetId = 'ECMWF/CAMS/NRT';
    const band = 'pm2p5';
    console.log(`Dataset: ${datasetId} (${band})`);

    // Helper to get monthly stats with optional widened window
    async function getMonthlyStats(year, month) {
      const start = ee.Date.fromYMD(year, month, 1);
      const end = start.advance(1, 'month');
      const col = ee.ImageCollection(datasetId).select(band).filterDate(start, end);
      const size = await col.size().getInfo();
      if (size === 0) {
        // Widen window ±15 days around month
        const startW = start.advance(-15, 'day');
        const endW = end.advance(15, 'day');
        const colW = ee.ImageCollection(datasetId).select(band).filterDate(startW, endW);
        const sizeW = await colW.size().getInfo();
        if (sizeW === 0) {
          return {year, month, usedWiden: false, size: 0, mean: null, count: 0};
        }
        const imgW = colW.mean();
        const dictW = await imgW.reduceRegion({
          reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
          geometry: region,
          scale: scale,
          maxPixels: 1e9
        }).getInfo();
        const meanW = dictW ? dictW[band + '_mean'] : null;
        const countW = dictW ? dictW[band + '_count'] : 0;
        return {year, month, usedWiden: true, size: sizeW, mean: meanW, count: countW};
      } else {
        const img = col.mean();
        const dict = await img.reduceRegion({
          reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
          geometry: region,
          scale: scale,
          maxPixels: 1e9
        }).getInfo();
        const mean = dict ? dict[band + '_mean'] : null;
        const count = dict ? dict[band + '_count'] : 0;
        return {year, month, usedWiden: false, size: size, mean: mean, count: count};
      }
    }

    // 2. Acquire stats for Feb 2019 and Feb 2020
    const s2019 = await getMonthlyStats(2019, 2);
    const s2020 = await getMonthlyStats(2020, 2);

    // 3. Empty collection checks
    if (s2019.size === 0 || s2020.size === 0) {
      console.log(`2019-02 imgs: ${s2019.size}`);
      console.log(`2020-02 imgs: ${s2020.size}`);
      console.log('One or both months have no images even after widening.');
      console.log('C1');
      return;
    }

    // 4. Print sizes and widen info
    console.log(`2019-02 imgs: ${s2019.size}${s2019.usedWiden ? ' (widened window)' : ''}`);
    console.log(`2020-02 imgs: ${s2020.size}${s2020.usedWiden ? ' (widened window)' : ''}`);

    // 5. Valid pixels check
    if (!s2019.count || !s2020.count || s2019.count === 0 || s2020.count === 0) {
      console.log(`2019-02 px: ${s2019.count || 0}`);
      console.log(`2020-02 px: ${s2020.count || 0}`);
      console.log('C2');
      return;
    }

    // 6. Calculation and validation
    const v2019 = s2019.mean;
    const v2020 = s2020.mean;
    const invalid = (v) => (v === null || !isFinite(v) || v < 0 || v > 2000);
    if (invalid(v2019) || invalid(v2020)) {
      console.log(`2019-02 mean: ${v2019}`);
      console.log(`2020-02 mean: ${v2020}`);
      console.log('C3');
      return;
    }

    console.log(`2019-02 mean(ug/m3): ${v2019.toFixed(2)}, px: ${s2019.count}`);
    console.log(`2020-02 mean(ug/m3): ${v2020.toFixed(2)}, px: ${s2020.count}`);
    const diff = v2020 - v2019;
    console.log(`Diff 2020-2019 (ug/m3): ${diff.toFixed(2)}`);

    // 7. Final Answer
    if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    // Any dataset, band, syntax, or runtime errors
    console.log(String(err).split('\n')[0]);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
